refentry.refsect1:
&reftitle.description;
intfalsefileperms stringfilename
Lit les droits du fichier donné.

  &reftitle.examples;



    Affichage des droits en valeur octale


<?php
echo substr(sprintf('%o', fileperms('/tmp')), -4);
echo substr(sprintf('%o', fileperms('/etc/passwd')), -4);
?>


    &example.outputs;


1777
0644




    Affichage de tous les droits


<?php
$perms = fileperms('/etc/passwd');

switch ($perms & 0xF000) {
    case 0xC000: $info = 's'; break; // Socket
    case 0xA000: $info = 'l'; break; // Lien symbolique
    case 0x8000: $info = 'r'; break; // Régulier
    case 0x6000: $info = 'b'; break; // Bloc spécial
    case 0x4000: $info = 'd'; break; // dossier
    case 0x2000: $info = 'c'; break; // Caractère spécial
    case 0x1000: $info = 'p'; break; // pipe FIFO

    // Inconnu
    default: $info = 'u';
}

// Propriétaire
$setuid = $perms & 0x0800;
$info .= (($perms & 0x0100) ? 'r' : '-');
$info .= (($perms & 0x0080) ? 'w' : '-');
$info .= (($perms & 0x0040) ? ($setuid ? 's' : 'x') : ($setuid ? 'S' : '-'));

// Groupe
$setgid = $perms & 0x0400;
$info .= (($perms & 0x0020) ? 'r' : '-');
$info .= (($perms & 0x0010) ? 'w' : '-');
$info .= (($perms & 0x0008) ? ($setgid ? 's' : 'x') : ($setgid ? 'S' : '-'));

// Tout le monde
$sticky = $perms & 0x0200;
$info .= (($perms & 0x0004) ? 'r' : '-');
$info .= (($perms & 0x0002) ? 'w' : '-');
$info .= (($perms & 0x0001) ? ($sticky ? 't' : 'x') : ($sticky ? 'T' : '-'));

echo $info;
?>


    &example.outputs;


-rw-r--r--
